<script setup lang="ts">
import type { Report } from '~/types/lapormas'
definePageMeta({ layout: 'app', middleware: 'auth', title: 'Dashboard Admin' })
const { state, verifyReport, currentUser } = useLaporMas()
const pending = computed(() => state.value.reports.filter(r => r.status === 'Menunggu verifikasi'))
const publicCount = computed(() => state.value.reports.filter(r => ['Terverifikasi', 'Ditangani', 'Selesai'].includes(r.status)).length)
const resolved = computed(() => state.value.reports.filter(r => r.status === 'Selesai').length)
const usersCount = computed(() => state.value.users.filter(u => u.active).length)
const note = ref('')
function confirm(id: string, approved: boolean) { verifyReport(id, approved, note.value); note.value = '' }
const latest = computed(() => [...state.value.reports].sort((a,b) => b.createdAt.localeCompare(a.createdAt)).slice(0, 5))
</script>
<template><div class="page-stack"><div class="page-title-row"><div><div class="eyebrow">PUSAT KENDALI LINGKUNGAN</div><h1>Dashboard admin</h1><p>Kelola laporan masuk dan pastikan setiap aduan mendapat tindak lanjut.</p></div><NuxtLink to="/admin/pengguna" class="btn btn-outline">＋ Tambah akun</NuxtLink></div><div class="stats-grid"><StatCard label="Menunggu verifikasi" :value="pending.length" helper="Perlu pemeriksaan" icon="◷" tone="amber"/><StatCard label="Laporan terpublikasi" :value="publicCount" helper="Valid & terlihat warga" icon="▤" tone="blue"/><StatCard label="Selesai ditangani" :value="resolved" helper="Hasil petugas tersedia" icon="✓" tone="green"/><StatCard label="Akun aktif" :value="usersCount" helper="Seluruh peran" icon="♙"/></div><section class="panel"><div class="panel-heading"><div><div class="eyebrow">TINDAKAN DIPERLUKAN</div><h3>Antrean verifikasi</h3><p>Pastikan laporan valid sebelum tampil ke warga.</p></div><span class="count-pill">{{ pending.length }} menunggu</span></div><div v-if="pending.length" class="review-list"><div v-for="report in pending" :key="report.id" class="review-item"><div class="review-item-main"><div class="report-kicker"><span>{{ report.category }}</span><span>·</span><span>{{ report.ticket }}</span></div><NuxtLink :to="`/app/laporan/${report.id}`"><h3>{{ report.title }}</h3></NuxtLink><p>{{ report.description }}</p><div class="report-meta"><span>⌖ {{ report.location }}</span><span>Oleh {{ report.ownerName }}</span></div></div><div class="review-actions"><NuxtLink :to="`/app/laporan/${report.id}`" class="btn btn-outline btn-small">Periksa detail</NuxtLink><button class="btn btn-primary btn-small" @click="confirm(report.id, true)">Verifikasi ✓</button><button class="text-button danger-text" @click="confirm(report.id, false)">Tolak laporan</button></div></div></div><EmptyState v-else title="Antrean bersih" description="Tidak ada laporan yang menunggu verifikasi saat ini." icon="✓"/></section><section class="panel"><div class="panel-heading"><div><h3>Aktivitas laporan terbaru</h3><p>Pembaruan laporan yang masuk ke portal.</p></div><NuxtLink to="/app/laporan" class="subtle-link">Lihat semua ↗</NuxtLink></div><div class="table-wrap"><table class="data-table"><thead><tr><th>LAPORAN</th><th>PELAPOR</th><th>TANGGAL</th><th>STATUS</th><th></th></tr></thead><tbody><tr v-for="report in latest" :key="report.id"><td><b>{{ report.title }}</b><small>{{ report.ticket }}</small></td><td>{{ report.ownerName }}</td><td>{{ new Date(report.createdAt).toLocaleDateString('id-ID', { day:'2-digit', month:'short', year:'numeric' }) }}</td><td><StatusBadge :status="report.status"/></td><td><NuxtLink :to="`/app/laporan/${report.id}`" class="row-action">↗</NuxtLink></td></tr></tbody></table></div></section></div></template>
